makeQuiz("quiz2","score2",[{"q": "Trong mô hình ISA-95, MES làm việc ở cấp nào?", "o": ["Cấp 1", "Cấp 2", "Cấp 3", "Cấp 4"], "a": 2, "e": "Cấp 3 là quản lý vận hành sản xuất, nơi MES làm việc. Cấp 4 là ERP; cấp 2 là SCADA, HMI."}, {"q": "Một màn hình HMI cạnh máy hiện sản lượng và cho bấm chạy, dừng. HMI thuộc cấp nào?", "o": ["Cấp 2, vì nó giám sát và điều khiển giám sát một máy", "Cấp 3, vì nó có số liệu sản lượng", "Cấp 1, vì nó gắn trên máy", "Cấp 4, vì người quản lý xem được"], "a": 0, "e": "Cấp xếp theo chức năng. Có số liệu sản lượng không làm HMI thành MES: HMI không quản lý lệnh, lô, ca của xưởng."}, {"q": "Vì sao dữ liệu được gộp dần khi đi lên các cấp?", "o": ["Vì mạng ở cấp cao chậm hơn", "Vì mỗi cấp cao hơn làm việc với khung thời gian dài hơn và cần thông tin tổng hợp", "Vì ISA-95 cấm gửi dữ liệu chi tiết", "Vì ERP không có cơ sở dữ liệu"], "a": 1, "e": "ERP lập kế hoạch theo ngày, tuần, tháng nên cần sản lượng tổng; dữ liệu từng hộp vẫn được MES giữ để truy xuất."}, {"q": "Đơn 9 000 hộp chia cho 3 ca, MES ghi mã sản phẩm 7 vào D110. PLC nhận được thông tin gì?", "o": ["Đơn 9 000 hộp và tên khách hàng", "Số hộp của từng ca", "Chỉ mã sản phẩm 7", "Toàn bộ lệnh sản xuất"], "a": 2, "e": "PLC chỉ cần mã sản phẩm để chọn thông số chạy. Đơn hàng, khách hàng, kế hoạch theo ca do ERP và MES giữ."}, {"q": "Rủi ro chính khi cho ERP đọc thẳng bộ đếm D102 của PLC là gì?", "o": ["PLC sẽ đếm chậm lại", "ERP không đọc được số 32 bit", "Mạng sẽ bị quá tải ngay lập tức", "Con số thiếu ngữ cảnh lệnh, ca, reset, và mở đường kết nối từ văn phòng tới PLC"], "a": 3, "e": "Một con số trần trụi không cho biết nó thuộc lệnh nào, ca nào, bộ đếm có bị reset không. Kết nối trực tiếp còn là rủi ro an ninh OT."}]);

